    "id": "uea-vestibular-2025-g1-q33",
    "exam": "UEA Unificado — Específicos Grupo I",
    "year": 2025,
    "phase": "Específicos Grupo I",
    "kind": "objective",
    "institution": "UEA",
    "board": "VUNESP",
